ubmit" name="status" value="deactivated">Deactivate</button><?php elseif($account['role']==='customer'): ?><button class="btn btn-sm" type="submit" name="status" value="active">Activate</button><?php endif; ?><?php if($account['role']==='admin' && $account['status']==='active'): ?><button class="btn btn-light btn-sm" type="submit" name="status" value="suspended">Suspend</button><?php endif; ?></div></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">👥</span><h3>No users match this filter</h3><p>Try another role, status, or search term.</p></div><?php endif; ?></div>
